function state(id,data,lang){const unknown=!!data?.unavailable,owned=!!data?.unlockedCharacterIds?.includes(id),equipped=owned&&data?.equippedCharacterId===id,stage=root.ArcCrew?.get(id)?.stage||0;return {owned,equipped,stage,unknown,label:unknown?local(lang,'所有状況はゲームで確認','Check ownership in game'):local(lang,equipped?'編成中':owned?'解放済み':'未解放',equipped?'In formation':owned?'Unlocked':'Locked'),action:unknown?local(lang,'ゲームで確認','Check in game'):local(lang,equipped?'現在の機体':owned?'編成する':stage+'面クリアで解放',equipped?'Current machine':owned?'Use this machine':'Clear stage '+stage+' to unlock')};}
function art(id,options={}){const p=A().get(id),m=motions[id],entry=C()?.character(id),image=!root.ArcOfflinePreview&&entry?.verified&&entry.src?(root.ArcAssetLoader?root.ArcAssetLoader.resolve(entry.src,options.assetBase||root.ArcAssetBase||'../../'):new URL((options.assetBase||root.ArcAssetBase||'../../')+entry.src,document.baseURI).href):null;return `<div class="ch-art" data-hero-art="${id}" data-lang="${options.lang||'ja'}" data-asset-base="${esc(options.assetBase||root.ArcAssetBase||'../../')}" data-reveal-motion="${m[0]}" data-signature="${m[5]}" data-source="${image?'image-loading':'canvas'}" style="--machine-color:${p.color};--machine-light:${p.light}">${image?`<img src="${esc(image)}" alt="" aria-hidden="true" class="ch-ambient" hidden>`:''}<div class="ch-art-plane">${image?`<img src="${esc(image)}" alt="${p.name}" class="ch-image" width="${entry.width}" height="${entry.height}" decoding="async" hidden>`:''}<canvas class="ch-canvas" role="img" aria-label="${esc(p.name)}"></canvas><i class="ch-signature" aria-hidden="true"></i></div><span class="ch-art-origin">${local(options.lang,'ゲーム内デザイン','IN-GAME DESIGN')}</span></div>`;}
function markup(id,options={}){const p=A().get(id),lang=options.lang||'ja',s=state(id,options.data,lang),stats=root.ArcCombat?.get(id),no=String(A().characters.findIndex(c=>c.id===id)+1).padStart(2,'0'),extra=options.description||'';return `<section class="character-hero" data-machine="${id}" data-kind="${options.kind||'detail'}" data-story-raw style="--machine-color:${p.color};--machine-light:${p.light}">${art(id,options)}<div class="ch-copy"><div class="ch-copy-body"><small class="ch-id">${local(lang,'機体','MACHINE')} ${no}/10</small><h3 class="ch-name">${esc(p.name)}</h3><p class="ch-name-ja">${esc(p.nameJa)}</p><p class="ch-role">${esc(lang==='en'?p.role:p.roleJa)}</p><p class="ch-motto">${esc(lang==='en'?p.motto:p.mottoJa)}</p>${stats?`<p class="ch-facts">HP ${stats.hp} · ${local(lang,'チャージ','Charge')} ${stats.charge.rise}s</p><details class="ch-abilities"><summary>${local(lang,'通常弾・必殺技','Normal and special')}</summary><p>${esc(root.ArcI18n?.t(stats.normalNote)||stats.normalNote)}</p><strong>${esc(root.ArcI18n?.t(stats.special.name)||stats.special.name)}</strong><p>${esc(root.ArcI18n?.t(stats.specialNote)||stats.specialNote)}</p></details>`:''}${extra?`<p class="ch-description">${esc(extra)}</p>`:''}</div><p class="ch-state" role="status">${s.owned?'✓':lock} ${esc(s.label)}${!s.owned&&!s.unknown?' · '+local(lang,s.stage+'面で仲間に','Joins at stage '+s.stage):''}</p><button type="button" data-confirm-character="${id}" ${!s.owned||s.equipped?'disabled':''}>${esc(s.action)}</button></div></section>`;}
function tile(id,data,inspected,lang){const p=A().get(id),s=state(id,data,lang);return `<button type="button" data-inspect-character="${id}" aria-pressed="${id===inspected}" aria-label="${esc(p.name+' · '+(lang==='en'?p.role:p.roleJa)+' · '+s.label)}" class="${s.owned?'owned':'locked'} ${s.equipped?'equipped':''}">${A().markup(id)}<strong>${esc(lang==='en'?p.name:p.nameJa)}</strong><span class="roster-role">${esc(lang==='en'?p.role:p.roleJa)}</span><small>${s.equipped?'✓ ':!s.owned?lock:''}${esc(s.label)}</small></button>`;}
function label(e){const image=e.dataset.source==='verified-image';e.querySelector('.ch-art-origin').textContent=local(e.dataset.lang,image?'キャラクター原画':'ゲーム内デザイン',image?'CHARACTER ART':'IN-GAME DESIGN');}
function localizeArt(container,lang){for(const e of container.querySelectorAll('[data-hero-art]')){e.dataset.lang=lang;label(e);}}
function hydrate(container,options={}){for(const e of container.querySelectorAll('[data-hero-art]')){const id=e.dataset.heroArt,canvas=e.querySelector('canvas');e.dataset.elapsed=String(options.reveal?0:6);e.dataset.reveal=options.reveal?'true':'false';A().paint(canvas,id);const img=e.querySelector('.ch-image');if(img){const done=ok=>{if(!e.isConnected)return;e.dataset.source=ok?'verified-image':'canvas-fallback';for(const image of e.querySelectorAll('img'))image.hidden=!ok;canvas.hidden=ok;label(e);paint(e,Number(e.dataset.elapsed));};const attach=url=>{if(!e.isConnected)return;img.onload=()=>done(true);img.onerror=()=>done(false);if(url)img.src=url;if(img.complete&&img.naturalWidth)done(true);};if(root.ArcAssetLoader){root.ArcAssetLoader.load(C().character(id).src,{retries:2,timeout:10000,assetBase:e.dataset.assetBase}).then(result=>result.ok?attach(result.url):done(false));}else{attach();if(img.complete&&!img.naturalWidth)done(false);}}paint(e,Number(e.dataset.elapsed));}}
function framing(id,w,h,t,still=false){
 const entry=C().character(id),m=motions[id],f=entry.focalPoint.desktop,box=entry.protectedBox,progress=still?.5:root.ArcCinematicPlayer.ease(t/6),maxZoom=Math.max(m[3],m[4]),base=Math.min(Math.max(w/entry.width,h/entry.height),w/(entry.width*(box[2]-box[0])*maxZoom),h/(entry.height*(box[3]-box[1])*maxZoom)),bw=entry.width*base,bh=entry.height*base,z=still?1.02:m[3]+(m[4]-m[3])*progress,iw=bw*z,ih=bh*z,focus=still?entry.focalPoint[w/h<1?'mobile':'desktop']:[f[0]+m[1]+(m[2]-m[1])*progress,f[1]+(id==='sora'?.035-.06*progress:0)];
 const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));function offset(size,image,lo,hi,center){let n=clamp(size/2-center*image,-lo*image,size-hi*image);return image<size?clamp(n,0,size-image):clamp(n,size-image,0);}
 const x=offset(w,iw,box[0],box[2],focus[0]),y=offset(h,ih,box[1],box[3],focus[1]);return {x,y,scale:z,baseWidth:bw,baseHeight:bh,protected:{left:x+box[0]*iw,top:y+box[1]*ih,right:x+box[2]*iw,bottom:y+box[3]*ih}};
}
function paint(e,t){const id=e.dataset.heroArt,m=motions[id],rm=root.matchMedia?.('(prefers-reduced-motion: reduce)').matches,low=root.ArcCinematicPlayer?.restricted(),ratio=rm||low?1:root.ArcCinematicPlayer.ease(t/6),w=e.clientWidth,plane=e.querySelector('.ch-art-plane');
 if(e.dataset.source==='verified-image'){const g=framing(id,w,e.clientHeight,t,rm||low);e._artGeometry=g;plane.style.inset='auto';plane.style.left='0';plane.style.top='0';plane.style.width=g.baseWidth+'px';plane.style.height=g.baseHeight+'px';plane.style.transformOrigin='0 0';plane.style.transform=`translate3d(${g.x}px,${g.y}px,0) scale(${g.scale})`;}
 else{delete e._artGeometry;plane.style.inset='0';plane.style.width='';plane.style.height='';plane.style.transformOrigin='50% 65%';const dx=rm||low?0:(m[1]+(m[2]-m[1])*ratio)*Math.min(w,500),dy=rm||low?0:(id==='sora'?-8:id==='mogu'?5:0)*(1-ratio),z=rm||low?1:m[3]+(m[4]-m[3])*ratio;plane.style.transform=`translate3d(${dx}px,${dy}px,0) scale(${z})`;}
 e.dataset.lowPerformance=String(!!low);const signature=e.querySelector('.ch-signature'),opacity=rm||low?0:Math.sin(Math.PI*Math.max(0,Math.min(1,(t-3)/1.2)));signature.style.opacity=String(Math.max(0,opacity)*.32);e.style.setProperty('--reveal-age',String(t));if(e.dataset.reveal==='true'){const panel=e.closest('#expeditionDialog');if(panel)for(const [i,id]of ['expeditionMachineName','expeditionName','expeditionRole','expeditionMotto'].entries()){const field=panel.querySelector('#'+id),f=rm?1:root.ArcCinematicPlayer.ease((t-[1.5,1.7,2.2,2.6][i])/.35);field.style.opacity=String(f);field.style.transform=`translate3d(0,${(1-f)*16}px,0)`;}}}
function updateAll(dt,container=document){if(document.hidden)return;for(const e of container.querySelectorAll('[data-hero-art]')){if(!e.getClientRects().length)continue;const t=Math.min(7,Number(e.dataset.elapsed||0)+dt);e.dataset.elapsed=String(t);paint(e,t);}}
