function snapshot(container){const source=container?.querySelector('.character-hero:not(.ch-previous)');if(!source)return null;const old=source.cloneNode(true),a=source.querySelectorAll('canvas'),b=old.querySelectorAll('canvas');for(let i=0;i<a.length;i++){b[i].width=a[i].width;b[i].height=a[i].height;b[i].getContext('2d').drawImage(a[i],0,0);}for(const b of old.querySelectorAll('[data-confirm-character]')){b.removeAttribute('data-confirm-character');b.disabled=true;b.tabIndex=-1;}for(const e of old.querySelectorAll('[data-hero-art]'))e.removeAttribute('data-hero-art');old.removeAttribute('data-machine');old.setAttribute('aria-hidden','true');old.inert=true;old.classList.remove('ch-incoming');old.classList.add('ch-previous');return old;}
